7	const DEFAULT: BuyerContext = { province: "ON", loyalty: false, conquest: false };
8	const NEW_COOKIE = "buyer-context";
9	const LEGACY_COOKIE = "buyer-province";
10	const ONE_YEAR = 60 * 60 * 24 * 365;
11	
12	function readCookie(): BuyerContext {
13	  if (typeof document === "undefined") return DEFAULT;
14	  const m = document.cookie.match(/(?:^|;\s*)buyer-context=([^;]+)/);
15	  if (m) {
16	    try {
17	      return BuyerContextSchema.parse(JSON.parse(decodeURIComponent(m[1])));
18	    } catch {
19	      // fall through
20	    }
21	  }
22	  // Legacy single-province cookie (set before loyalty/conquest landed).
23	  const lm = document.cookie.match(/(?:^|;\s*)buyer-province=([A-Z]{2})/);
24	  if (lm && (PROVINCES as readonly string[]).includes(lm[1])) {
25	    return { ...DEFAULT, province: lm[1] as Province };
26	  }
27	  return DEFAULT;
28	}
29	
30	function writeCookie(value: BuyerContext) {
31	  if (typeof document === "undefined") return;
32	  const v = encodeURIComponent(JSON.stringify(value));
33	  document.cookie = `${NEW_COOKIE}=${v}; path=/; max-age=${ONE_YEAR}; SameSite=Lax`;
34	  // Also keep the legacy cookie current so any code still reading the
35	  // single-string cookie stays consistent. Safe to drop after every caller
36	  // moves to buyer-context.
37	  document.cookie = `${LEGACY_COOKIE}=${value.province}; path=/; max-age=${ONE_YEAR}; SameSite=Lax`;
38	}
