40	export function useBuyerContext(): {
41	  buyerContext: BuyerContext;
42	  setBuyerContext: (next: BuyerContext) => void;
43	} {
44	  const [buyerContext, setState] = useState<BuyerContext>(DEFAULT);
45	
46	  useEffect(() => {
47	    setState(readCookie());
48	  }, []);
49	
50	  const setBuyerContext = useCallback((next: BuyerContext) => {
51	    writeCookie(next);
52	    setState(next);
53	    // Reload so server components recompute OTD + applicable incentives
54	    // against the new context. Cheap on a personal-use SPA.
55	    if (typeof window !== "undefined") {
56	      window.location.reload();
57	    }
58	  }, []);
59	
60	  return { buyerContext, setBuyerContext };
61	}
